import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts
 *
 * POST /internal/posts — Create a new post (community discussion thread)
 * @Valid @RequestBody CreatePostRequest with userId, title, category, content, moodEmoji, nickname
 * Response: CreatePostResponse with generated postId; DB stores Post with likes=0, createdAt=now
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CreatePostBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "USER_ID", "user" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/create-post-teardown.sql", p);
        executeSqlTemplate("sql/create-post-setup.sql", p);
    }

    @Test
    void NTC_createPost_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"userId\": \"" + p.get("USER_ID") + "\", \"title\": \"My Story\", \"category\": \"daily\", \"content\": \"Today was a great day\", \"moodEmoji\": \"😄\", \"nickname\": \"Happy\"}")
            .when()
                    .post("/internal/posts")
            .then()
                    .statusCode(201)
                    .body("postId", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("2", queryScalar("SELECT COUNT(*) as cnt FROM post WHERE user_id = ?", p.get("USER_ID")));
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", p);
        }
    }

    @Test
    void NTC_createPost_success_noMoodEmoji(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"userId\": \"" + p.get("USER_ID") + "\", \"title\": \"Another Story\", \"category\": \"career\", \"content\": \"Career progress update\", \"nickname\": \"Professional\"}")
            .when()
                    .post("/internal/posts")
            .then()
                    .statusCode(201)
                    .body("postId", notNullValue());
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", p);
        }
    }

    @Test
    void VTC_createPost_missingTitle(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"userId\": \"" + p.get("USER_ID") + "\", \"title\": \"\", \"category\": \"daily\", \"content\": \"Content without title\", \"nickname\": \"Test\"}")
            .when()
                    .post("/internal/posts")
            .then()
                    .statusCode(400)
                    .body("error", notNullValue());
        } finally {
            executeSqlTemplate("sql/create-post-teardown.sql", p);
        }
    }

    @Test

